"""
Module for remotely collecting logs from Egen.

This module provides the EgenLogsCollector class, which uses Moler to connect
to a remote host, start and stop the Egen log collection process, and download
the resulting .pcap files. It simplifies the management of Egen instances for
automated testing and data gathering.

:copyright: Nokia Networks
:author: Mateusz Potoniec
:maintainer: Mateusz Potoniec
:contact: mateusz.potoniec@nokia.com

Usage:
    from taf.rfrl.utilities.egen import EgenLogsCollector

    # Collector configuration
    host_ip = "10.0.0.1"
    login = "user"
    password = "password"
    local_log_dir = "/tmp/logs"
    log_file_name = "capture_run_1.pcap"

    # Create an instance of the collector
    collector = EgenLogsCollector()

    try:
        # Start log collection on the remote machine
        collector.start_logs_collection(
            host=host_ip,
            login=login,
            password=password,
            file_name=log_file_name,
            cores="1,2",
            ports=["0", "1"]
        )

        # ... perform actions that generate network traffic ...

    finally:
        # Stop collection and download the log file
        downloaded_path = collector.stop_logs_collection_and_download_logs(local_log_dir, log_file_name)
        # ... perform further logs processing ...
"""

import os
from typing import List, Optional

from moler.device import DeviceFactory

from taf.ul.moler.converter import add_unix_remote_device_to_already_loaded_configuration
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.transfer_files import download_files


class EgenLogsCollector:
    def __init__(self):
        """
        Initialize EgenLogsCollector.
        The class collects Egen logs using remote host, and stores it to pcap file.
        The class uses Moler to connect to Egen device and start/stop logs collection.
        """

        self._egen_device_name = 'EGEN'
        self._egen_device = None
        self._egen_cmd = None
        self._egen_cmd_object = None

    @property
    def egen_cmd(self) -> str:
        """
        Get the Egen command string.

        :return: The Egen command string.
        """

        return self._egen_cmd

    @load_moler_configuration_from_tl()
    def start_logs_collection(self, host: str, login: str, password: str, file_name: str, cores: str,
                              ports: List[str], additional_options: Optional[str] = None,
                              egen_path: str = "./egen", use_sudo: bool = True,
                              timeout: int = 600) -> str:
        """
        Start Egen logs collection.

        :param host: Hostname or IP address of the Egen device.
        :param login: Login for the Egen device.
        :param password: Password for the Egen device.
        :param file_name: Name of the file to store the logs: (Egen CMD parameter) (with extension .pcap).
        :param cores: Number of cores to use for Egen logs collection: (Egen CMD parameter).
        :param ports: List of ports to use for Egen logs collection: (Egen CMD parameter).
        :param additional_options: Additional options for Egen logs collection: (Egen CMD parameter).
        :param egen_path: Path to the Egen executable on the remote device (Default: "./egen").
        :param use_sudo: Whether to use sudo to run the Egen command (Default: True).
        :param timeout: Timeout for the Egen logs collection command in seconds (Default: 600s).

        :return: The Egen command object.
        """

        self._create_egen_device(host, login, password)
        self._create_egen_cmd(cores, ports, additional_options, file_name, egen_path, use_sudo)
        self._create_egen_cmd_object()

        self._egen_cmd_object.start(timeout=timeout)
        return file_name

    def stop_logs_collection(self) -> None:
        """
        Stop Egen logs collection.
        """

        self._egen_cmd_object.cancel()

    def download_logs(self, local_dir: str, file_name: str, remote_dir: str = "/home/egenuser") -> str:
        """
        Download Egen logs from the device to the local directory.

        :param local_dir: Local directory to store the downloaded logs.
        :param file_name: Name of the file to download.
        :param remote_dir: Remote directory where the logs are stored (Default: "/home/egenuser").

        :return: Path to the downloaded logs file.
        """

        download_files(
            local_dir=local_dir,
            remote_file=file_name,
            device_name=self._egen_device_name,
            remote_dir=remote_dir,
        )
        return os.path.join(local_dir, file_name)

    def stop_logs_collection_and_download_logs(self, local_dir: str, file_name: str,
                                               remote_dir: str = "/home/egenuser") -> str:
        """
        Stop Egen logs collection and download logs to the local directory.

        :param local_dir: Local directory to store the downloaded logs
        :param file_name: Name of the file to download.
        :param remote_dir: Remote directory where the logs are stored (Default: "/home/egenuser").

        :return: Path to the downloaded logs file.
        """

        self.stop_logs_collection()
        return self.download_logs(local_dir=local_dir, file_name=file_name, remote_dir=remote_dir)

    def _create_egen_cmd(self, cores: str, ports: List[str], additional_options: Optional[str],
                         file_name: str, egen_path: str, use_sudo: bool) -> None:
        """
        Create Egen start logs collection command.

        :param cores: Number of cores to use for Egen logs collection.
        :param ports: List of ports to use for Egen logs collection.
        :param additional_options: Additional options for Egen logs collection.
        :param file_name: Name of the file to store the logs.
        :param egen_path: Path to the Egen executable on the remote device.
        :param use_sudo: Whether to use sudo to run the Egen command.
        """

        command = f"sudo {egen_path} " if use_sudo else f"{egen_path} "

        command = command + f"--cores {cores} "
        for port in ports:
            command = command + f"--port {port} "

        if additional_options is not None:
            command = command + f"{additional_options} "
        command = command + f"--capture {file_name}"

        self._egen_cmd = command

    def _create_egen_cmd_object(self) -> None:
        """
        Creates and sets the Egen cmd moler object as a class attribute.
        """

        self._egen_cmd_object = self._egen_device.get_cmd(
            cmd_name='run_script',
            cmd_params={'script_command': self._egen_cmd, 'error_regex': '.*error.*([1-9][0-9]+|[1-9])'}
        )

    @load_moler_configuration_from_tl()
    def _create_egen_device(self, host: str, login: str, password: str) -> None:
        """
        Creates and sets the Egen Moler device as a class attribute.

        :param host: Hostname or IP address of the Egen device.
        :param login: Login for the Egen device.
        :param password: Password for the Egen device.
        """

        add_unix_remote_device_to_already_loaded_configuration(
            host=host,
            login=login,
            password=password,
            device_name=self._egen_device_name
        )
        self._egen_device = DeviceFactory.get_device(name=self._egen_device_name)
